def can_download_document(user, document):
    role = user_role(user)
    if role == Profile.CUSTOMER_CONTACT:
        return user.profile.organization_id == document.organization_id and document.visibility == "customer"
    return can_access_org(user, document.organization)

def visible_orgs(user):
    role = user_role(user)
    if role == Profile.PLATFORM_ADMIN:
        return Organization.objects.all()
    if role == Profile.ACCOUNT_MANAGER:
        return Organization.objects.filter(owner=user)
    if role == Profile.SUPPORT_AGENT:
        return Organization.objects.filter(escalations__assigned_agent=user).distinct()
    if role == Profile.CUSTOMER_CONTACT:
        return Organization.objects.filter(id=user.profile.organization_id)
    return Organization.objects.none()

