def organization_list(request):
    orgs = visible_orgs(request.user)
    q = request.GET.get("q", "")
    if q:
        orgs = orgs.filter(Q(name__icontains=q) | Q(billing_contact_email__icontains=q))
    for field in ["plan", "status", "health"]:
        value = request.GET.get(field)
        if value:
            orgs = orgs.filter(**{field: value})
    return render(request, "operations/organization_list.html", {"orgs": orgs, "q": q})

